 'admin_config'=>static function()use($database){
  $s=new WbceEmailFactorService($database);$h=static function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};$languages=$s->installedLanguages();$preferred=defined('LANGUAGE')?strtoupper((string)LANGUAGE):'';if(!isset($languages[$preferred])){$keys=array_keys($languages);$preferred=(string)($keys[0]??'');}
  $templates=array();foreach($languages as $code=>$name){$subject=$s->setting('subject.'.$code,'');$message=$s->setting('message.'.$code,'');$templates[$code]=array('subject'=>$subject!==''?$subject:$s->textForLanguage('default_subject',$code),'message'=>$message!==''?$message:$s->textForLanguage('default_message',$code));}
  $current=$templates[$preferred]??array('subject'=>'','message'=>'');$html='<form class="two-factor-email-config"><label>'.$h(wbce_two_factor_t('validity',array(),'two_factor_email')).'<select name="validity"><option value="300"'.($s->setting('validity','300')==='300'?' selected':'').'>5 '.$h(wbce_two_factor_t('minutes',array(),'two_factor_email')).'</option><option value="600"'.($s->setting('validity')==='600'?' selected':'').'>10 '.$h(wbce_two_factor_t('minutes',array(),'two_factor_email')).'</option></select></label><label>'.$h(wbce_two_factor_t('edit_language',array(),'two_factor_email')).'<select name="target_language" data-email-language-picker>';
  foreach($languages as $code=>$name)$html.='<option value="'.$h($code).'"'.($code===$preferred?' selected':'').'>'.$h($name.' ('.$code.')').'</option>';
  $legend=wbce_two_factor_t('language_template',array('language'=>($languages[$preferred]??$preferred).' ('.$preferred.')'),'two_factor_email');
  $mailerReady=$s->isConfigured();
  $html.='</select></label><p class="wide tf-mailer-status'.($mailerReady?' is-ready':'').'"><small>'.$h(wbce_two_factor_t($mailerReady?'mailer_ready':'mailer_not_ready',array(),'two_factor_email')).'</small></p><p class="wide"><small>'.$h(wbce_two_factor_t('placeholder_help',array(),'two_factor_email')).'</small></p><fieldset class="wide" data-email-template-fields><legend data-email-language-legend>'.$h($legend).'</legend><label>'.$h(wbce_two_factor_t('subject',array(),'two_factor_email')).'<input name="subject" value="'.$h($current['subject']).'" maxlength="190" required></label><label>'.$h(wbce_two_factor_t('message_template',array(),'two_factor_email')).'<textarea name="message" rows="5" required>'.$h($current['message']).'</textarea></label></fieldset><script type="application/json" data-email-language-templates>'.json_encode(array('templates'=>$templates,'names'=>$languages),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP).'</script>';
  $html.='<script>(function(script){var form=script.closest("form"),picker=form&&form.querySelector("[data-email-language-picker]"),source=form&&form.querySelector("[data-email-language-templates]"),subject=form&&form.querySelector("[name=subject]"),message=form&&form.querySelector("[name=message]"),legend=form&&form.querySelector("[data-email-language-legend]"),payload={templates:{},names:{}};if(!picker||!source||!subject||!message)return;try{payload=JSON.parse(source.textContent)}catch(ignore){}function show(){var code=picker.value,item=(payload.templates||{})[code]||{subject:"",message:""},name=(payload.names||{})[code]||code;subject.value=item.subject||"";message.value=item.message||"";if(legend)legend.textContent=name+" ("+code+")"}picker.addEventListener("change",show);if(window.jQuery)window.jQuery(picker).on("change select2:select",show);show()})(document.currentScript);</script>';
  return $html.'<button type="submit" class="button">'.$h(wbce_two_factor_t('save',array(),'two_factor_email')).'</button></form>';
