 'save_config'=>static function($input)use($database){$s=new WbceEmailFactorService($database);$languages=$s->installedLanguages();$target=strtoupper(trim((string)($input['target_language']??'')));if(!isset($languages[$target]))throw new RuntimeException(wbce_two_factor_t('language_invalid',array(),'two_factor_email'));$subject=trim((string)($input['subject']??''));$message=trim((string)($input['message']??''));if($subject===''||$message===''||strpos($message,'{code}')===false)throw new RuntimeException(wbce_two_factor_t('template_invalid',array(),'two_factor_email'));if(!$s->setSetting('subject.'.$target,$subject)||!$s->setSetting('message.'.$target,$message))throw new RuntimeException(wbce_two_factor_t('save_failed',array(),'two_factor_email'));$validity=(string)($input['validity']??'300');if(!in_array($validity,array('300','600'),true))$validity='300';if(!$s->setSetting('validity',$validity))throw new RuntimeException(wbce_two_factor_t('save_failed',array(),'two_factor_email'));}
